Journey step registrarPagamentoMensalidade/localizarMensalidade motivates this BFF call.

// bffCall qryListMensalidades (query) — Output kind=paginated; route mensalidadesAcademia.pagamentosMensalidades.qryListMensalidades.
export interface QryListMensalidadesInput {
  matriculaId: string;
  competencia: string;
  situacao?: string;
  page?: number;
  pageSize?: number;
}

export interface QryListMensalidadesOutputItem {
  id: string;
  matriculaId: string;
  competencia: string;
  vencimento: string;
  valorCobranca: number;
  totalPago: number;
  saldoDevedor: number;
  situacao: string;
}

export interface QryListMensalidadesOutput {
  mensalidadeItems: QryListMensalidadesOutputItem[];
  total: number;
  page?: number;
  pageSize?: number;
}

export const qryListMensalidadesRoute = 'mensalidadesAcademia.pagamentosMensalidades.qryListMensalidades' as const;

l4 entity: Mensalidade
l4 fields: Mensalidade.matriculaId, Mensalidade.competencia, Mensalidade.details.situacao, Mensalidade.id, Mensalidade.vencimento, Mensalidade.details.valorCobranca, Mensalidade.details.totalPago, Mensalidade.details.saldoDevedor
